import { test, expect } from 'bun:test';
import { assignRole } from '../src/assign.js';
const make = () => {
  const users = [['a', 'admin'], ['o', 'owner'], ['e', 'editor'], ['v', 'viewer']].map(([id, role]) => [id, { id, role }]);
  return { users: new Map(users) };
};
test('an admin can assign a lower role', () => {
  const db = make();
  const u = assignRole(db, db.users.get('a'), 'v', 'editor');
  expect(u.role).toBe('editor');
  expect(db.users.get('v').role).toBe('editor');
});
test('an owner can make an admin', () => {
  const db = make();
  expect(assignRole(db, db.users.get('o'), 'e', 'admin').role).toBe('admin');
});
test('editors and viewers cannot assign roles', () => {
  const db = make();
  expect(() => assignRole(db, db.users.get('e'), 'v', 'editor')).toThrow();
  expect(db.users.get('v').role).toBe('viewer');
});
test('unknown user or role throws', () => {
  const db = make();
  expect(() => assignRole(db, db.users.get('a'), 'nobody', 'editor')).toThrow();
  expect(() => assignRole(db, db.users.get('a'), 'v', 'wizard')).toThrow();
});

