import { test, expect } from 'bun:test';
import { assignRole } from '../src/assign.js';
const make = () => new Map([['a', 'admin'], ['a2', 'admin'], ['o', 'owner'], ['v', 'viewer']].map(([id, role]) => [id, { id, role }]));
const tryAssign = (db, actor, target, role) => { try { assignRole(db, db.users.get(actor), target, role); return 'ok'; } catch { return 'threw'; } };
test('nobody can grant a role above their own, whatever the case of the name', () => {
  const db = { users: make() };
  for (const role of ['owner', 'OWNER', 'Owner']) {
    expect(tryAssign(db, 'a', 'v', role)).toBe('threw');
    expect(db.users.get('v').role).toBe('viewer');
  }
  expect(tryAssign(db, 'a', 'v', 'admin')).toBe('ok');
  expect(db.users.get('v').role).toBe('admin');
});
test('nobody can change their own role', () => {
  const db = { users: make() };
  expect(tryAssign(db, 'a', 'a', 'viewer')).toBe('threw');
  expect(tryAssign(db, 'o', 'o', 'admin')).toBe('threw');
  expect(db.users.get('a').role).toBe('admin');
  expect(db.users.get('o').role).toBe('owner');
});
test('an admin cannot change a user who outranks them', () => {
  const db = { users: make() };
  expect(tryAssign(db, 'a', 'o', 'viewer')).toBe('threw');
  expect(db.users.get('o').role).toBe('owner');
  expect(tryAssign(db, 'a', 'a2', 'viewer')).toBe('ok');
});
